// AsKnownAmount returns the union data inside the AmountValue as a KnownAmount
func (t AmountValue) AsKnownAmount() (KnownAmount, error) {
	var body KnownAmount
	err := json.Unmarshal(t.union, &body)
	return body, err
}

// FromKnownAmount overwrites any union data inside the AmountValue as the provided KnownAmount
func (t *AmountValue) FromKnownAmount(v KnownAmount) error {
	b, err := json.Marshal(v)
	t.union = b
	return err
}

// MergeKnownAmount performs a merge with any union data inside the AmountValue, using the provided KnownAmount
func (t *AmountValue) MergeKnownAmount(v KnownAmount) error {
	b, err := json.Marshal(v)
	if err != nil {
		return err
	}

	merged, err := runtime.JSONMerge(t.union, b)
	t.union = merged
	return err
}

